"""Trimmed DP-GEN generator snapshot for task 082."""

from __future__ import annotations

import os
from packaging.version import Version


def find_only_one_key(lmp_lines, key):
    found = []
    for idx in range(len(lmp_lines)):
        words = lmp_lines[idx].split()
        nkey = len(key)
        if len(words) >= nkey and words[:nkey] == key:
            found.append(idx)
    if len(found) > 1:
        raise RuntimeError("found %d keywords %s" % (len(found), key))  # noqa: UP031
    if len(found) == 0:
        raise RuntimeError(f"failed to find keyword {key}")
    return found[0]


def _model_devi_keywords(workflow_options):
    """Collect the pair_style model-deviation keywords from the workflow options."""
    tokens = []
    if not workflow_options:
        return tokens
    if workflow_options.get("use_clusters", False):
        tokens.append("atomic")
    if workflow_options.get("use_relative", False):
        tokens.append("relative {}".format(workflow_options["epsilon"]))
    if workflow_options.get("use_relative_v", False):
        tokens.append("relative_v {}".format(workflow_options["epsilon_v"]))
    return tokens


def _ele_temp_token(use_ele_temp):
    """Map the electron-temperature style to its pair_style keyword token."""
    if use_ele_temp == 0:
        return None
    if use_ele_temp == 1:
        return "fparam ${ELE_TEMP}"
    if use_ele_temp == 2:
        return "aparam ${ELE_TEMP}"
    raise ValueError(f"unsupported use_ele_temp value: {use_ele_temp}")


def revise_lmp_input_model(
    lmp_lines,
    task_model_list,
    trj_freq,
    deepmd_version="1",
    use_ele_temp=0,
    workflow_options=None,
):
    idx = find_only_one_key(lmp_lines, ["pair_style", "deepmd"])
    graph_list = " ".join(task_model_list)
    if Version(deepmd_version) < Version("1"):
        lmp_lines[idx] = "pair_style      deepmd %s %d model_devi.out\n" % (  # noqa: UP031
            graph_list,
            trj_freq,
        )
    else:
        extra_tokens = _model_devi_keywords(workflow_options)
        ele_temp_token = _ele_temp_token(use_ele_temp)
        if ele_temp_token is not None:
            extra_tokens.append(ele_temp_token)
        line = "pair_style      deepmd %s out_freq %d out_file model_devi.out"  # noqa: UP031
        line = line % (graph_list, trj_freq)
        if extra_tokens:
            line = f"{line} {' '.join(extra_tokens)}"
        lmp_lines[idx] = line + "\n"
    return lmp_lines


def build_template_options(settings, use_ele_temp=None):
    ele_temp_f = settings.get("ele_temp_f")
    ele_temp_a = settings.get("ele_temp_a")
    if ele_temp_f is not None and ele_temp_a is not None:
        raise RuntimeError(
            "the frame style ele_temp and atom style ele_temp should not be set at the same time"
        )
    if use_ele_temp is None:
        if ele_temp_f is not None:
            use_ele_temp = 1
        elif ele_temp_a is not None:
            use_ele_temp = 2
        else:
            use_ele_temp = 0
    deepmd_version = settings.get("deepmd_version", "1")
    if use_ele_temp != 0 and Version(deepmd_version) < Version("1"):
        raise RuntimeError(
            "the electron temperature is only supported by deepmd-kit >= 1.0.0, please upgrade your deepmd-kit"
        )
    workflow_options = settings.get("workflow_options")
    if not isinstance(workflow_options, dict):
        workflow_options = {}
    template_options = dict(settings.get("template_options", {}))
    template_options.update(
        {
            "deepmd_version": deepmd_version,
            "use_ele_temp": use_ele_temp,
            "workflow_options": workflow_options,
        }
    )
    return template_options


def render_external_template_input(template_lines, task_model_list, trj_freq, template_options):
    revised_lines = list(template_lines)
    options = dict(template_options)
    workflow_options = options.get("workflow_options")
    if not isinstance(workflow_options, dict):
        workflow_options = {}
    model_devi_merge_traj = bool(
        options.get(
            "model_devi_merge_traj",
            workflow_options.get("model_devi_merge_traj", False),
        )
    )
    revised_lines = revise_lmp_input_model(
        revised_lines, task_model_list, trj_freq, **options
    )
    revised_lines = revise_lmp_input_dump(
        revised_lines, trj_freq, model_devi_merge_traj=model_devi_merge_traj
    )
    return revised_lines


def revise_lmp_input_dump(lmp_lines, trj_freq, model_devi_merge_traj=False):
    idx = find_only_one_key(lmp_lines, ["dump", "dpgen_dump"])
    if model_devi_merge_traj:
        lmp_lines[idx] = (
            "dump            dpgen_dump all custom %d    all.lammpstrj id type x y z\n"  # noqa: UP031
            % trj_freq
        )
        has_restart_append = any(
            "dump_modify" in " ".join(line.split()) for line in lmp_lines
        )
        if not has_restart_append:
            lmp_lines.insert(
                idx + 1,
                'if "${restart} > 0" then "dump_modify     dpgen_dump append yes"\n',
            )
    else:
        lmp_lines[idx] = (
            "dump            dpgen_dump all custom %d traj/*.lammpstrj id type x y z\n"  # noqa: UP031
            % trj_freq
        )
        lmp_lines[:] = [
            line
            for line in lmp_lines
            if "dump_modify" not in " ".join(line.split())
        ]

    return lmp_lines


def revise_lmp_input_plm(lmp_lines, in_plm, out_plm="output.plumed"):
    idx = find_only_one_key(lmp_lines, ["fix", "dpgen_plm"])
    lmp_lines[idx] = (
        f"fix            dpgen_plm all plumed plumedfile {in_plm} outfile {out_plm}\n"
    )
    return lmp_lines


def revise_by_keys(lmp_lines, keys, values):
    for kk, vv in zip(keys, values):
        for ii in range(len(lmp_lines)):
            words = lmp_lines[ii].split()
            if len(words) > 0 and words[0] == kk:
                lmp_lines[ii] = vv + "\n"
    return lmp_lines


if os.environ.get("DPGEN_TASK082_DEBUG") == "1":
    # Keep this module importable as a standalone snapshot.
    pass
